_TEMPLATE_PATH = "/tmp/hsa_checklist_template.docx"


def _ensure_template() -> str:
    """Materializa o template embutido pra disco. Idempotente."""
    if os.path.exists(_TEMPLATE_PATH) and os.path.getsize(_TEMPLATE_PATH) > 100_000:
        return _TEMPLATE_PATH
    raw = gzip.decompress(base64.b64decode(_TEMPLATE_B64_GZ.replace("\n", "")))
    with open(_TEMPLATE_PATH, "wb") as f:
        f.write(raw)
    return _TEMPLATE_PATH


# ── Mapeamento ordem-do-template → chave no frontend ──────────────────────
# Os 12 itens aparecem na mesma ordem no template original e no estado
# `files` do app.jsx. Se um dia mexer no template, ajustar esta lista.
_ITEMS_IN_ORDER = [
    "certidao",        # 1
    "familia",         # 2
    "dirpf",           # 3
    "dcbe",            # 4
    "alteracoes",      # 5
    "societario_br",   # 6
    "societario_off",  # 7
    "lei_14754",       # 8
    "imoveis",         # 9
    "emprestimos",     # 10
    "doacoes",         # 11
    "previdencia",     # 12
]


def _esc(s: str) -> str:
    """Escape XML reservados + transforma aspas em entidades unicode."""
    return (s.replace("&", "&amp;")
              .replace("<", "&lt;")
              .replace(">", "&gt;")
              .replace('"', "&quot;"))


def _status_run_xml(is_done: bool) -> str:
    """
    Run XML adicionado ao FINAL de cada item da lista.

    Bold + colorido — verde RFC #2E8B57 pra "Concluído", vermelho #C8102E pra
    "Pendente". Antecedido por espaço pra separar do texto do item.

    Reutiliza fonte e tamanho do parágrafo pai por herança (sem rPr → herda).
    """
    if is_done:
        label = "Concluído"
        color = "2E8B57"
    else:
        label = "Pendente"
        color = "C8102E"
    return (
        '<w:r>'
          '<w:rPr>'
            f'<w:b/><w:bCs/>'
            f'<w:color w:val="{color}"/>'
          '</w:rPr>'
          f'<w:t xml:space="preserve"> — {label}</w:t>'
        '</w:r>'
    )


def build_checklist(client_name: str, file_status: dict, output_path: str) -> str:
    """
    Gera o checklist preenchido. `file_status` é um dict {key: bool} onde as
    keys correspondem a _ITEMS_IN_ORDER e o bool indica se o doc foi recebido.
    Keys faltando viram False (Pendente).

    Retorna output_path.
    """
    template_path = _ensure_template()

    # Trabalhar num diretório temporário; .docx é um zip, então abrimos,
    # editamos os XMLs internos e empacotamos de novo.
    with tempfile.TemporaryDirectory() as tmp:
        work_dir = Path(tmp) / "work"
        work_dir.mkdir()
        # Extrai o .docx
        with zipfile.ZipFile(template_path, "r") as zf:
            zf.extractall(work_dir)

        doc_xml_path = work_dir / "word" / "document.xml"
        xml = doc_xml_path.read_text(encoding="utf-8")

        # ── 1) Substituir nome do cliente ──────────────────────────────
        # O template usa duas formas distintas:
        #   "JANE DOE"  → no título (uma única vez)
        #   "JANE"      → apelido entre aspas + uso ao longo do texto
        #
        # Pra não duplicar (ex: virar "MARCELO ANDRADE (\"MARCELO ANDRADE\")"
        # se substituirmos os dois com o mesmo valor), tratamos de forma
        # diferente: nome completo no título, apelido curto no apelido.
        #
        # Apelido = primeiro nome do cliente em CAPS, ou o nome inteiro se
        # for de uma palavra só.
        name_upper = (client_name or "CLIENTE").upper().strip()
        first = name_upper.split()[0] if name_upper else "CLIENTE"
        nickname = first

        # IMPORTANTE: substituir "JANE DOE" ANTES de "JANE" pra evitar
        # double-replacement.
        xml = xml.replace("JANE DOE", _esc(name_upper))
        # Agora substitui "JANE" isolado pelo apelido em todo lugar que ainda
        # tiver. Usa \b pra não pegar substrings dentro de outras palavras.
        xml = re.sub(r"\bJANE\b", _esc(nickname), xml)

        # ── 2) Anexar status "Concluído"/"Pendente" a cada item ─────────
        # Cada item da lista é um <w:p> que contém <w:numId w:val="1"/>.
        # Inserimos o run de status antes do </w:p> do parágrafo.
        #
        # CRÍTICO: o regex precisa NÃO cruzar fronteiras de </w:p>. Sem o
        # negative-lookahead, o ".*?" do re.DOTALL pode pular pra dentro do
        # próximo parágrafo e capturar o título junto com o item 1, fazendo
        # o status aparecer no lugar errado.
        item_index = [0]  # mutável em closure

        def _inject_status(match: re.Match) -> str:
            para = match.group(0)
            i = item_index[0]
            if i >= len(_ITEMS_IN_ORDER):
                return para
            key = _ITEMS_IN_ORDER[i]
            is_done = bool(file_status.get(key, False))
            item_index[0] += 1
            run_xml = _status_run_xml(is_done)
            return para.replace("</w:p>", run_xml + "</w:p>", 1)

        # Match: <w:p ...> seguido de QUALQUER coisa que NÃO seja </w:p>,
        # contendo <w:numId w:val="1"/>, terminando em </w:p>. O grupo
        # `(?:(?!</w:p>).)*?` é o truque pra não vazar pro próximo paragrafo.
        para_pattern = re.compile(
            r'<w:p[ >](?:(?!</w:p>).)*?<w:numId\s+w:val="1"/>(?:(?!</w:p>).)*?</w:p>',
            re.DOTALL,
        )
        xml = para_pattern.sub(_inject_status, xml)

        doc_xml_path.write_text(xml, encoding="utf-8")

        # ── 3) Reempacotar como .docx ─────────────────────────────────
        # Necessário preservar a ordem e estrutura interna do zip.
        out_zip = Path(output_path)
        out_zip.parent.mkdir(parents=True, exist_ok=True)
        if out_zip.exists():
            out_zip.unlink()

        with zipfile.ZipFile(out_zip, "w", zipfile.ZIP_DEFLATED) as zf:
            for path in sorted(work_dir.rglob("*")):
                if path.is_file():
                    arcname = str(path.relative_to(work_dir))
                    zf.write(path, arcname)

    return str(output_path)
